const i = $json ?? {};
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
// El teléfono del canal manda; el que diga el cliente solo vale si el canal no da ninguno.
const telefono = clean(i.telefono) || clean(i.telefono_dicho);
const asunto = clean(i.asunto);
const tz = clean(i.tenant_timezone) || 'Europe/Madrid';

if (!asunto) {
  return [{ json: { _ok: false, ok: false, motivo: 'faltan_datos',
    detalle: 'Necesito saber qué hay que anotar.' } }];
}
if (!telefono) {
  return [{ json: { _ok: false, ok: false, motivo: 'falta_identidad', falta: ['telefono'] } }];
}

// Mismo prefijo por tipo que en v1: quien lo lea en Directus ve de un vistazo qué es.
const PREFIJO = { callback: 'Llamar', review_doc: 'Revisar', admin: 'Gestión', email: 'Email' };
const tipo = clean(i.tipo).toLowerCase();
const prefijo = PREFIJO[tipo] || null;

// En los recados de llamada el agente calca la frase del cliente ("dile a Arturo que me
// llame para hablar del contrato de X") y el titular sale larguísimo, repitiendo la acción
// (ya está en el tipo), a quién se le asigna (assignee_id) y quién lo pide (contact_id).
// Solo para 'callback', y solo si la frase tiene esa forma exacta, nos quedamos con el
// tema. Si no encaja o no queda nada, el asunto se deja intacto: el peor caso es el
// título de antes, nunca uno equivocado.
let asuntoTitulo = asunto;
if (tipo === 'callback') {
  const m = asunto.match(
    /^que\s+.*?\bllam\w*\b.*?\b(?:para|sobre|acerca de|respecto a|porque|por)\s+(.+)$/i);
  if (m) {
    const tema = m[1].replace(/^(?:hablar|tratar|comentar|charlar)\s+(?:de|del|sobre|acerca de)\s+/i, '').trim();
    if (tema.length >= 3) asuntoTitulo = tema.charAt(0).toUpperCase() + tema.slice(1);
  }
}
// Si el asunto ya empieza por el verbo del tipo no se antepone: si no, salen títulos como
// "Revisar: Revisar presupuesto...". Se compara por la raíz para que "Llamada"/"Revisión"
// cuenten igual que "Llamar"/"Revisar".
const sinTildes = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const raiz = prefijo ? sinTildes(prefijo).slice(0, 4) : '';
const yaLoDice = raiz && sinTildes(asuntoTitulo).startsWith(raiz);
const title = (prefijo && !yaLoDice) ? (prefijo + ': ' + asuntoTitulo) : asuntoTitulo;

const PRIORIDADES = ['low', 'normal', 'high', 'urgent'];
const p = clean(i.prioridad).toLowerCase();
const priority = PRIORIDADES.includes(p) ? p : 'normal';

// due_at es opcional. Sin hora se asume final de la mañana, como hacía v1.
let due_at = '';
let fecha_limite_label = null;
const fecha = clean(i.fecha_limite);
if (/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
  const hora = /^\d{2}:\d{2}$/.test(clean(i.hora_limite)) ? clean(i.hora_limite) : '13:00';
  const dt = DateTime.fromISO(fecha + 'T' + hora, { zone: tz });
  if (dt.isValid) {
    due_at = dt.toISO();
    fecha_limite_label = dt.setLocale('es').toFormat("cccc d 'de' LLLL");
  }
}

// La descripción no es el título repetido: es lo que necesita quien abra la tarea en
// Directus sin haber visto la conversación. `detalle` lo redacta el agente; el mensaje
// literal del cliente lo ponemos nosotros, porque es el único trozo que no puede salir
// parafraseado (y a veces el matiz está justo ahí).
const detalle = clean(i.detalle);
const mensaje = clean(i.mensaje_original);
const canal = clean(i.canal);
const bloques = [detalle || asunto];
if (mensaje && mensaje.toLowerCase() !== asunto.toLowerCase()) {
  bloques.push('Mensaje del cliente: «' + mensaje + '»');
}
const pie = [];
if (canal) pie.push('Recibido por ' + canal);
if (fecha_limite_label) pie.push('para el ' + fecha_limite_label);
if (pie.length) bloques.push(pie.join(', ') + '.');

return [{ json: { _ok: true, telefono, title, priority, due_at, fecha_limite_label,
  asunto, description: bloques.join('\n\n'),
  para_quien: clean(i.para_quien),
  directus_base_url: clean(i.directus_base_url) } }];

const r = $json ?? {};
const inp = $('Code · Entrada').first().json;
const asg = $('Code · Resolver empleado').first().json;
const tarea = { asunto: inp.asunto, prioridad: inp.priority,
                fecha_limite_label: inp.fecha_limite_label,
                asignada_a: asg.asignada_a || null,
                asignacion: asg.asignacion,
                candidatos: asg.candidatos || undefined };
if (r.ok === true) {
  return [{ json: { ok: true, motivo: 'anotada', tarea, telefono_usado: inp.telefono } }];
}
const st = r.status || 'error';
if (st === 'not_found') {
  // El contacto no existe: para una tarea hace falta a quién asociarla.
  return [{ json: { ok: false, motivo: 'falta_identidad', falta: ['nombre'] } }];
}
if (st === 'multiple') return [{ json: { ok: false, motivo: 'contacto_ambiguo',
  detalle: r.message || null } }];
return [{ json: { ok: false, motivo: 'error_tarea',
  status_origen: st, detalle: r.message || null } }];

// Estricto a propósito, como en todo lo demás: si no hay UNA coincidencia clara no se
// asigna a nadie. La tarea se crea igual -- perder el recado sería peor que dejarlo sin
// asignar -- pero se dice qué pasó para que Lucía no afirme que se lo ha pasado a alguien
// que no existe o que podría ser otro.
const inp = $('Code · Entrada').first().json;
if (!inp.para_quien) return [{ json: { assignee_id: '', asignacion: 'no_pedida' } }];

const r = $json ?? {};
const body = (r.body ?? r) || {};
if ((r.statusCode ?? 0) >= 300 || body.errors) {
  return [{ json: { assignee_id: '', asignacion: 'error_busqueda' } }];
}
const filas = Array.isArray(body.data) ? body.data : [];
const nombre = e => [e.first_name, e.last_name].filter(Boolean).join(' ');

if (filas.length === 1) {
  return [{ json: { assignee_id: filas[0].id, asignacion: 'asignada',
    asignada_a: nombre(filas[0]) } }];
}
if (filas.length > 1) {
  return [{ json: { assignee_id: '', asignacion: 'varios_empleados',
    candidatos: filas.map(nombre) } }];
}
return [{ json: { assignee_id: '', asignacion: 'empleado_desconocido' } }];
